ui/editorial-product-card.code:
"use client";

import type { MouseEvent } from "react";
import styles from "./styles.module.css";

export interface ProductSpecItem {
  label: string;
  value: string;
}

export interface EditorialProductCardProps {
  title: string;
  price: string;
  specs?: ProductSpecItem[];
  variant?: "wireframe" | "tile";
  href?: string;
  actionTitle?: string;
  imageSrc?: string;
  imageAlt?: string;
  hoverSummary?: string;
  className?: string;
  onAction?: (event: MouseEvent<HTMLAnchorElement>) => void;
}

const DEFAULT_SPECS: ProductSpecItem[] = [
  { label: "Type", value: "Single Origin" },
  { label: "Origin", value: "Nicaragua" },
  { label: "Process", value: "Washed" },
];

function formatLabel(label: string): string {
  return label.endsWith(":") ? label : `${label}:`;
}

export function EditorialProductCard({
  title,
  price,
  specs = DEFAULT_SPECS,
  variant = "wireframe",
  href = "#",
  actionTitle,
  imageSrc,
  imageAlt,
  hoverSummary,
  className,
  onAction,
}: EditorialProductCardProps) {
  const handleClick = (event: MouseEvent<HTMLAnchorElement>) => {
    if (onAction) {
      onAction(event);
      return;
    }
    if (href === "#") {
      event.preventDefault();
    }
  };

  if (variant === "tile") {
    const tileClass = className ? `${styles.tile} ${className}` : styles.tile;
    return (
      <article className={tileClass}>
        <a
          href={href}
          className={styles.tileLink}
          title={actionTitle ?? `Select ${title}`}
          onClick={handleClick}
        >
          {imageSrc ? (
            <img
              src={imageSrc}
              alt={imageAlt ?? title}
              className={styles.tileImg}
            />
          ) : (
            <div className={styles.tileFallback} aria-hidden="true" />
          )}

          <div className={styles.tileInfos}>
            <h3 className={styles.tileTitle}>{title}</h3>
            <p className={styles.price}>{price}</p>
          </div>

          <div className={styles.tileHover}>
            {hoverSummary ? <p>{hoverSummary}</p> : null}
            <table className={styles.specTable}>
              <tbody>
                {specs.map((spec) => (
                  <tr key={spec.label} className={styles.specRow}>
                    <td className={styles.specLabel}>{formatLabel(spec.label)}</td>
                    <td className={styles.specValue}>{spec.value}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </a>
      </article>
    );
  }

  const cardClass = className ? `${styles.card} ${className}` : styles.card;

  return (
    <article className={cardClass}>
      <a
        href={href}
        className={styles.cardLink}
        title={actionTitle ?? `Select ${title}`}
        onClick={handleClick}
      >
        <div className={styles.infos}>
          <h3 className={styles.title}>{title}</h3>
          <p className={styles.price}>{price}</p>
        </div>

        <table className={styles.specTable}>
          <tbody>
            {specs.map((spec) => (
              <tr key={spec.label} className={styles.specRow}>
                <td className={styles.specLabel}>{formatLabel(spec.label)}</td>
                <td className={styles.specValue}>{spec.value}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </a>
    </article>
  );
}

ui/editorial-product-card.stylesCss:
.card {
  display: block;
  height: 100%;
  overflow: hidden;
  border-radius: 10px;
  box-shadow: 0 0 0 1.5px currentColor;
  background-color: transparent;
  color: var(--rk-bg);
  font-family: var(--rk-font-body);
  font-size: 16px;
  font-weight: 300;
  line-height: 1;
}

.cardLink {
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  height: 100%;
  padding: 15px 20px;
  background-color: transparent;
  color: inherit;
  text-decoration: none;
  transition: background-color 0.6s cubic-bezier(0.37, 0.31, 0, 1),
    color 0.6s cubic-bezier(0.37, 0.31, 0, 1);
}
.cardLink:hover,
.cardLink:active,
.cardLink:focus {
  background-color: var(--rk-bg);
  color: var(--rk-fg);
}
.cardLink:focus-visible,
.tileLink:focus-visible {
  outline: 2px solid var(--rk-accent);
  outline-offset: -2px;
}

.infos {
  display: flex;
  column-gap: 20px;
}

.title {
  display: block;
  margin: 0 0 40px;
  font-family: var(--rk-font-display);
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: normal;
  text-transform: uppercase;
}

.price {
  display: block;
  margin: 0 0 0 auto;
  font-family: var(--rk-font-body);
  font-size: 16px;
  font-weight: 300;
  line-height: 1.35;
}

.specTable {
  display: table;
  width: 100%;
  margin-top: auto;
  border-collapse: collapse;
  font-family: var(--rk-font-narrow, var(--rk-font-display));
  font-size: 15px;
  font-weight: 300;
  line-height: 1;
  letter-spacing: normal;
  text-transform: uppercase;
}
.specRow {
  display: grid;
  grid-template-columns: 70px auto;
  column-gap: 20px;
}
.specRow + .specRow {
  margin-top: 5px;
}
.specLabel {
  padding: 0;
  font-weight: 300;
}
.specValue {
  padding: 0;
  font-weight: 700;
}

.tile {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  aspect-ratio: 423 / 525;
  overflow: hidden;
  border-radius: var(--rk-radius-md, 4px);
  background-color: var(--rk-surface);
  color: var(--rk-fg);
  font-family: var(--rk-font-body);
  font-size: 16px;
  font-weight: 300;
  line-height: 1;
}

.tileLink {
  position: relative;
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: 24px 20px;
  color: inherit;
  text-decoration: none;
}

.tileImg,
.tileFallback {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(1) translateZ(0);
  transition: transform 0.5s cubic-bezier(0.645, 0.045, 0.355, 1);
}
.tileImg {
  width: 80%;
  height: auto;
}
.tileFallback {
  width: 62%;
  aspect-ratio: 3 / 4;
  border-radius: var(--rk-radius-sm, 2px);
  border: 1px solid var(--rk-border-strong);
  background: color-mix(in srgb, var(--rk-bg) 82%, var(--rk-surface));
}

.tileInfos {
  position: relative;
  display: flex;
  width: 100%;
  align-items: flex-end;
  justify-content: space-between;
  column-gap: 20px;
  margin-top: auto;
}
.tileTitle {
  margin: 0;
  font-family: var(--rk-font-display);
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  text-transform: uppercase;
}

.tileHover {
  position: absolute;
  inset: 24px 20px;
  z-index: 1;
  display: flex;
  flex-direction: column;
  padding: 20px;
  border-radius: var(--rk-radius-md, 4px);
  background-color: var(--rk-fg);
  color: var(--rk-bg);
  visibility: hidden;
  opacity: 0;
  transition: opacity 0.3s cubic-bezier(0.215, 0.61, 0.355, 1), visibility 0s linear 0.3s;
}
.tileHover p {
  margin: 0 0 16px;
  line-height: 1;
}
.tile:hover .tileHover,
.tile:focus-within .tileHover {
  visibility: visible;
  opacity: 1;
  transition: opacity 0.4s cubic-bezier(0.215, 0.61, 0.355, 1) 0.2s, visibility 0s linear;
}
.tile:hover .tileImg,
.tile:focus-within .tileImg,
.tile:hover .tileFallback,
.tile:focus-within .tileFallback {
  transform: translate(-50%, -50%) scale(1.1) translateZ(0);
}

.previewStage {
  position: relative;
  width: 100%;
  padding: 28px 20px;
  border-radius: 10px;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--rk-fg) 94%, var(--rk-surface)) 0%,
    var(--rk-fg) 100%
  );
  color: var(--rk-bg);
}
.previewList {
  display: grid;
  grid-template-columns: 1fr;
  row-gap: 12px;
  width: 100%;
  margin: 0;
  padding: 0;
  list-style: none;
}

@media only screen and (min-width: 1024px) {
  .card + .card {
    margin-left: 1.5px;
  }
  .title,
  .tileTitle {
    font-size: min(1.80556vw, 3.20988vh);
  }
  .price,
  .specTable {
    font-size: min(18px, min(1.25vw, 2.22222vh));
  }
  .previewStage {
    left: 50%;
    width: fit-content;
    max-width: calc(100vw - 40px);
    padding: 48px 44px;
    transform: translateX(-50%);
  }
  .previewList {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    row-gap: 0;
    width: calc(65.03vw - 25px);
