extraFiles.slider-math.ts:
export type SliderLayout = { slideW: number; step: number; total: number; half: number; containerW: number };

const PARALLAX_EXP = 0.84;
const PARALLAX_RANGE = 0.78;

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));

/** Positions every slide on the infinite loop and shifts each image for the parallax drift. */
export function renderSlides(
  layout: SliderLayout,
  slides: HTMLElement[],
  imgs: (HTMLElement | null)[],
  extra: number[],
  offset: number,
  reduced: boolean,
) {
  const { step, total, half, containerW, slideW } = layout;
  if (!total) return;
  const base = containerW / 2 - slideW / 2;
  for (let i = 0; i < slides.length; i++) {
    let x = i * step - offset;
    x = ((x % total) + total) % total;
    if (x > half) x -= total;
    slides[i].style.transform = `translate3d(${base + x}px, 0, 0)`;
    const img = imgs[i];
    if (!reduced && img) {
      const overflow = extra[i] || 0;
      const range = ((containerW + slideW) / 2) * PARALLAX_RANGE;
      const p = range ? clamp(-x / range, -1, 1) : 0;
      const shift = (p === 0 ? 0 : Math.sign(p) * Math.pow(Math.abs(p), PARALLAX_EXP)) * overflow;
      img.style.transform = `translate3d(calc(-50% + ${shift}px), 0, 0)`;
    }
  }
}

section/orchard-product-detail-hero.code:
"use client";

import { Fragment, useEffect, useRef, type MouseEvent } from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { OrchardSpinningJar, jarArt, labelArt } from "@registry/ui/orchard-spinning-jar/component";
import styles from "./styles.module.css";

export interface OrchardProductDetailHeroProps {
  id?: string;
  /** Monumental product name; "\n" becomes a line break. */
  title?: string;
  /** Left meta line, usually the category. */
  category?: string;
  categoryHref?: string;
  onCategoryClick?: (e: MouseEvent<HTMLAnchorElement>) => void;
  /** Right meta line; "\n" becomes a line break. */
  originLabel?: string;
  jarImage?: string;
  labelImage?: string;
  jarAlt?: string;
  /** Hides the jar while a flying clone is still landing. */
  jarPending?: boolean;
  /** Called with the jar element once its label has been drawn. */
  onJarReady?: (jar: HTMLElement) => void;
  ariaLabel?: string;
  className?: string;
}

const META_GAP_BELOW_JAR = 60;
const MOBILE_META_GAP = 16;
const SCROLL_FACTOR = 0.4;
const TITLE_MIN_TOP = 56;
const TITLE_JAR_GAP = 24;
const HEADER_PAD = 16;
const TITLE_REST_LOW = 0.5;
const TITLE_REST_HIGH = 0.6;

const Lines = ({ text }: { text: string }) => (
  <>
    {text.split("\n").map((line, i) => (
      <Fragment key={i}>
        {i > 0 ? <br /> : null}
        {line}
      </Fragment>
    ))}
  </>
);

export function OrchardProductDetailHero({
  id,
  title = "Pistachio\nCream",
  category = "Spreadable Creams",
  categoryHref,
  onCategoryClick,
  originLabel = "Made in\nSicily - Italy",
  jarImage = jarArt("goldenrod"),
  labelImage = labelArt("PISTACHIO", "Velvet Cream", "darkseagreen", "darkolivegreen"),
  jarAlt = "",
  jarPending = false,
  onJarReady,
  ariaLabel,
  className,
}: OrchardProductDetailHeroProps) {
  const rootRef = useRef<HTMLElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const titleRef = useRef<HTMLHeadingElement>(null);
  const metaRef = useRef<HTMLDivElement>(null);
  const jarRef = useRef<HTMLDivElement>(null);
  const spinRef = useRef<{ setSpin(p: number): void } | null>(null);
  const readyRef = useRef(onJarReady);
  useEffect(() => {
    readyRef.current = onJarReady;
  });

  useEffect(() => {
    const root = rootRef.current;
    if (!root || !jarRef.current) return;
    gsap.registerPlugin(ScrollTrigger);

    const layout = () => {
      const titleEl = titleRef.current;
      const jar = jarRef.current;
      const meta = metaRef.current;
      const stage = stageRef.current;
      if (!titleEl || !jar || !meta || !stage) return;
      meta.style.top = "";
      stage.style.removeProperty("--ph-title-rest-y");
      stage.style.removeProperty("--ph-title-fit");
      const mobile = window.matchMedia("(max-width: 1024px)").matches;
      const cs = getComputedStyle(root);
      const jarTop = jar.offsetTop;
      const scaleFrom = parseFloat(cs.getPropertyValue("--ph-jar-scale-from")) || 1;
      const safeTop = (parseFloat(cs.getPropertyValue("--header-safe-top")) || 0) + HEADER_PAD + (mobile ? meta.offsetHeight + MOBILE_META_GAP : 0);
      const jarTopScaled = jarTop - (jar.offsetHeight * (scaleFrom - 1)) / 2;
      const fullH = titleEl.offsetHeight;
      if (fullH > jarTopScaled - safeTop) stage.style.setProperty("--ph-title-fit", `${(jarTopScaled - safeTop) / fullH}`);
      const h = titleEl.offsetHeight;
      const clampY = (y: number) => Math.max(safeTop + h / 2, Math.min(y, jarTopScaled - h / 2));
      if (mobile) {
        const y = clampY(titleEl.offsetTop);
        stage.style.setProperty("--ph-title-rest-y", `${y}px`);
        stage.style.setProperty("--ph-title-fall", "0px");
        stage.style.setProperty("--ph-meta-shift", "0px");
        meta.style.top = `${y - h / 2 - MOBILE_META_GAP - meta.offsetHeight}px`;
        return;
      }
      const rise = cs.getPropertyValue("--ph-jar-rise").trim();
      const risePx = rise.endsWith("vh") ? (parseFloat(rise) * window.innerHeight) / 100 : parseFloat(rise) || 0;
      const jarCenter = jar.offsetTop + jar.offsetHeight / 2 + risePx;
      const stageH = stage.clientHeight;
      const minY = TITLE_MIN_TOP + h / 2;
      const maxY = jarTop - TITLE_JAR_GAP - h / 2;
      const k = Math.max(0, Math.min(1, (980 - stageH) / 220));
      const ratio = TITLE_REST_LOW + (TITLE_REST_HIGH - TITLE_REST_LOW) * k;
      const rest = Math.max(minY, Math.min(maxY, minY + (maxY - minY) * ratio));
      const restY = clampY(Math.min(rest, stageH * 0.52));
      stage.style.setProperty("--ph-title-rest-y", `${restY}px`);
      stage.style.setProperty("--ph-title-fall", `${jarCenter - restY}px`);
      stage.style.setProperty("--ph-meta-shift", `${jarCenter + h / 2 + META_GAP_BELOW_JAR - meta.offsetTop}px`);
    };

    let layoutRaf = 0;
    let ctx: gsap.Context | null = null;
    if (!window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      ctx = gsap.context(() => {
        ScrollTrigger.create({
          trigger: root,
          start: "top top",
          end: () => `+=${window.innerHeight * SCROLL_FACTOR}`,
          scrub: true,
          invalidateOnRefresh: true,
          onUpdate: (self) => {
            stageRef.current?.style.setProperty("--ph", `${self.progress}`);
            spinRef.current?.setSpin(self.progress);
          },
        });
      }, root);
      layoutRaf = requestAnimationFrame(layout);
      ScrollTrigger.addEventListener("refresh", layout);
    }
    return () => {
      cancelAnimationFrame(layoutRaf);
      ScrollTrigger.removeEventListener("refresh", layout);
      ctx?.revert();
    };
  }, [title, category, jarImage]);

  const metaLeft = categoryHref ? (
    <a href={categoryHref} onClick={onCategoryClick} className={`${styles.metaItem} ${styles.metaLeft} ${styles.metaLink}`}>
      {category}
    </a>
  ) : (
    <p className={`${styles.metaItem} ${styles.metaLeft}`}>{category}</p>
  );

  return (
    <section ref={rootRef} id={id} className={className ? `${styles.hero} ${className}` : styles.hero} aria-label={ariaLabel}>
      <div ref={stageRef} className={styles.stage}>
        <h1 ref={titleRef} className={styles.title} aria-label={title.replace(/\n/g, " ")}>
          <Lines text={title} />
        </h1>
        <div ref={metaRef} className={styles.meta}>
          <div className={styles.grid}>
            {metaLeft}
            <p className={`${styles.metaItem} ${styles.metaRight}`}>
              <Lines text={originLabel} />
            </p>
          </div>
        </div>
        {jarImage ? (
          <div ref={jarRef} className={styles.jar}>
            <OrchardSpinningJar
              jarImage={jarImage}
              labelImage={labelImage}
              alt={jarAlt}
              handleRef={spinRef}
              pending={jarPending}
              onReady={() => jarRef.current && readyRef.current?.(jarRef.current)}
              style={{ width: "100%" }}
            />
          </div>
        ) : null}
      </div>
    </section>
  );
}

section/orchard-product-detail-hero.stylesCss:
.hero {
  --header-pad-y: 30px;
  --header-brand-width: 135px;
  --header-safe-top: calc(var(--header-pad-y) + var(--header-brand-width) * 130 / 151);
  --ph-jar-scale-from: 1.25;
  --ph-jar-w: clamp(380px, 24vw, 99999px);
  --ph-jar-h: calc(var(--ph-jar-w) * 1013 / 630);
  --ph-jar-peek: 0.3;
  --ph-jar-bottom: calc((1 - var(--ph-jar-peek)) * var(--ph-jar-h) * -1);
  --ph-title-fall: 48vh;
  --ph-meta-shift: 0px;
  --ph-jar-rise: -24vh;
  --ph-jar-rotate: 20deg;
  --ph-jar-scale-to: 0.8;
  line-height: 1.3;
  overflow-x: clip;
  position: relative;
}

.stage {
  --ph: 0;
  background: var(--rk-bg);
  height: 100vh;
  height: 100dvh;
  position: relative;
}

.title {
  color: var(--rk-accent);
  font-family: var(--rk-font-display);
  font-size: calc(clamp(4rem, calc(2.9rem + 9vw), 999999px) * var(--ph-title-fit, 1));
  font-weight: 400;
  left: 50%;
  line-height: 0.9;
  margin: 0;
  position: absolute;
  text-align: center;
  text-transform: uppercase;
  top: var(--ph-title-rest-y, 48%);
  transform: translate(-50%, calc(-50% + var(--ph) * var(--ph-title-fall)));
  width: 95%;
  will-change: transform;
  z-index: 1;
}

.meta {
  bottom: 12%;
  left: 0;
  padding-left: clamp(30px, 2vw, 40px);
  padding-right: clamp(30px, 2vw, 40px);
  position: absolute;
  right: 0;
  z-index: 1;
}

.grid {
  display: grid;
  gap: 0 clamp(12px, 1.45vw, 30px);
  grid-template-columns: repeat(12, minmax(0, 1fr));
}

.metaItem {
  color: var(--rk-fg);
  font-family: var(--rk-font-display);
  font-size: 2rem;
  line-height: 1.1;
  margin: 0;
  min-width: 0;
  transform: translateY(calc(var(--ph) * var(--ph-meta-shift)));
  will-change: transform;
}

.metaLeft {
  grid-column: 2 / span 2;
  max-width: 200px;
}

.metaRight {
  grid-column: 10 / span 2;
  text-align: right;
}

.metaLink {
  display: inline-block;
  text-decoration: none;
  transition: color 0.3s ease;
  width: max-content;
}

.metaLink:hover,
.metaLink:focus-visible {
  color: var(--rk-accent);
}

.stage .jar {
  aspect-ratio: 630 / 1013;
  bottom: var(--ph-jar-bottom);
  height: auto;
  left: 50%;
  position: absolute;
  transform: translate(-50%) translateY(calc(var(--ph) * var(--ph-jar-rise)))
    rotate(calc(var(--ph) * var(--ph-jar-rotate)))
    scale(calc(var(--ph-jar-scale-from) + var(--ph) * (var(--ph-jar-scale-to) - var(--ph-jar-scale-from))));
  width: var(--ph-jar-w);
  will-change: transform;
  z-index: 2;
}

@media (max-width: 1024px) {
  .hero {
    --ph-jar-scale-to: 0.7;
    --ph-jar-w: clamp(250px, 40vh, 280px);
    --ph-jar-bottom: -30vh;
  }

  .meta > div {
    display: block;
    text-align: center;
  }

  .metaLeft {
    max-width: none;
  }

  .title {
    font-size: calc(clamp(4rem, calc(2.9rem + 6vw), 999999px) * var(--ph-title-fit, 1));
    line-height: 1;
  }

  .meta {
    bottom: auto;
    top: 35%;
  }

  .metaItem {
    text-transform: none;
  }

  .metaRight {
    display: none;
  }
}

@media (max-width: 480px) {
  .hero {
    --header-pad-y: 24px;
    --header-brand-width: 108px;
    --ph-jar-scale-to: 0.64;
    --ph-jar-w: clamp(250px, 40vh, 260px);
    --ph-jar-bottom: -35%;
  }

  .metaLeft {
    font-size: clamp(1.9rem, calc(1.6rem + 1.2vw), 2.2rem);
  }

  .title {
    font-size: calc(clamp(3rem, calc(1rem + 3vw), 999999px) * var(--ph-title-fit, 1));
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero {
    height: 100vh;
    height: 100dvh;
  }

  .jar,
  .meta,
  .title {
    transition: none;
  }
}

