            {conservation ? (
              <div className={styles.col}>
                <p className={styles.label}>{conservation.label}</p>
                <p className={styles.value}>{conservation.value}</p>
              </div>
            ) : null}
          </div>
        </div>
      </div>
    </section>
  );
}

