  display: flex;
  flex-direction: column;
  grid-column: 1 / -1;
  --container-padding: clamp(30px, 2vw, 40px);
  --grid-gap-x: clamp(12px, 1.45vw, 30px);
  --ledger-wide: calc(
    66.66667vw - var(--container-padding) * 2 / 12 * 8 - var(--grid-gap-x) * 11 / 12 * 8 +
      var(--grid-gap-x) * 7
  );
  --ledger-table: calc(
    83.33333vw - var(--container-padding) * 2 / 12 * 10 - var(--grid-gap-x) * 11 / 12 * 10 +
      var(--grid-gap-x) * 9
  );
  --ledger-narrow: calc(
    50vw - var(--container-padding) * 2 / 12 * 6 - var(--grid-gap-x) * 11 / 12 * 6 +
      var(--grid-gap-x) * 5
  );
}

.title {
  color: var(--rk-accent);
  font-family: var(--rk-font-display);
  font-size: clamp(4.1rem, calc(2.65rem + 5.95vw), 999999px);
  font-weight: 400;
  line-height: 1;
  margin: 0;
  text-align: center;
  text-transform: uppercase;
}

.text {
  color: var(--rk-fg);
  font-family: var(--rk-font-body);
  font-size: clamp(1.125rem, calc(1.085rem + 0.165vw), 1.25rem);
  letter-spacing: 0.014em;
  line-height: 1.3;
  margin-top: 6.25rem;
  max-width: var(--ledger-narrow);
  text-align: center;
  width: 100%;
}

.text p {
  line-height: 1.38;
  margin: 0;
}

.cover {
  aspect-ratio: 1004 / 615;
  border-radius: var(--rk-radius-md);
  margin: 6.25rem 0 0;
  max-width: var(--ledger-wide);
  overflow: hidden;
  position: relative;
  width: 100%;
}

.coverMedia {
  inset: -14% 0;
  position: absolute;
  will-change: transform;
}

.coverMedia img {
  display: block;
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.table {
  margin-top: 6.25rem;
  max-width: min(var(--ledger-table), 1200px);
  width: 100%;
}

.row {
  align-items: center;
  border-bottom: 1px solid color-mix(in srgb, var(--rk-fg) 20%, transparent);
  column-gap: var(--grid-gap-x);
  display: grid;
  grid-template-columns: 1fr 1fr auto;
  padding: 16px 0;
}

.cols2 .row {
  grid-template-columns: 1fr 27%;
}

.rowHead {
  border-bottom-color: var(--rk-fg);
}

.cell {
  color: var(--rk-fg);
  font-family: var(--rk-font-body);
  font-size: clamp(1.125rem, calc(1.085rem + 0.165vw), 1.25rem);
  line-height: 1.3;
}

.cellEnd {
  text-align: right;
}

.rowHead .cell {
  color: var(--rk-accent);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
}

@media (max-width: 1024px) {
  .inner {
    --ledger-wide: calc(
      83.33333vw - var(--container-padding) * 2 / 12 * 10 - var(--grid-gap-x) * 11 / 12 * 10 +
        var(--grid-gap-x) * 9
    );
    --ledger-narrow: var(--ledger-wide);
  }
}

@media (max-width: 480px) {
  .inner {
    --ledger-wide: 100%;
    --ledger-table: 100%;
    --ledger-narrow: 100%;
  }

  .cell {
    font-size: 0.875rem;
  }

  .row {
    padding: 12px 0;
  }
}

