// Procedural Canvas2D front and back card texture builder (zero external assets).

import { CanvasTexture, LinearMipmapLinearFilter, NoColorSpace } from "three";
import { drawAvatarDot, drawMotifPattern, MOTIF_THEMES, rgb, shieldPath } from "./deck-motifs";

export interface SpiralCardItem {
  id: number;
  house: string;
  title: string;
  body: string;
  duration?: string;
  extraCount?: number;
  patternIndex?: number;
}

export const CARD_WIDTH = 345;
export const CARD_HEIGHT = 490;
export const PLANE_WIDTH = 2.4;
export const PLANE_HEIGHT = (CARD_HEIGHT / CARD_WIDTH) * PLANE_WIDTH;
export const CARD_FONT = "-apple-system, system-ui, 'DM Sans', 'Helvetica Neue', sans-serif";
export const DEFAULT_FOOTER_NOTE = "In-person beats text for anything that matters.";

function wrapText(
  ctx: CanvasRenderingContext2D,
  text: string,
  x: number,
  y: number,
  maxWidth: number,
  lineHeight: number,
  maxLines = 99,
): number {
  let line = "";
  let lines = 0;
  const emit = (str: string) => {
    ctx.fillText(str, x, y);
    y += lineHeight;
    lines++;
  };
  for (let word of text.split(" ")) {
    const candidate = line ? `${line} ${word}` : word;
    if (ctx.measureText(candidate).width <= maxWidth) {
      line = candidate;
      continue;
    }
    if (line && (emit(line), (line = ""), lines >= maxLines)) return y;
    while (ctx.measureText(word).width > maxWidth) {
      let cut = 1;
      while (cut < word.length && ctx.measureText(word.slice(0, cut + 1)).width <= maxWidth) cut++;
      emit(word.slice(0, cut));
      if (lines >= maxLines) return y;
      word = word.slice(cut);
    }
    line = word;
  }
  if (line && lines < maxLines) emit(line);
  return y;
}

export function paintCardBack(canvas: HTMLCanvasElement, patternIdx: number, scale: number) {
  canvas.width = CARD_WIDTH * scale;
  canvas.height = CARD_HEIGHT * scale;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.setTransform(scale, 0, 0, scale, 0, 0);
  ctx.clearRect(0, 0, CARD_WIDTH, CARD_HEIGHT);
  ctx.save();
  ctx.beginPath();
  ctx.roundRect(0, 0, CARD_WIDTH, CARD_HEIGHT, 20);
  ctx.clip();
  drawMotifPattern(ctx, patternIdx, 0, 0, CARD_WIDTH, CARD_HEIGHT);
  ctx.restore();
}

export function paintCardFront(
  canvas: HTMLCanvasElement,
  card: SpiralCardItem,
  footerNote: string,
  scale: number,
) {
  canvas.width = CARD_WIDTH * scale;
  canvas.height = CARD_HEIGHT * scale;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  const patternIdx = card.patternIndex ?? (card.id % MOTIF_THEMES.length);
  const theme = MOTIF_THEMES[patternIdx % MOTIF_THEMES.length];

  ctx.setTransform(scale, 0, 0, scale, 0, 0);
  ctx.clearRect(0, 0, CARD_WIDTH, CARD_HEIGHT);
  ctx.beginPath();
  ctx.roundRect(0, 0, CARD_WIDTH, CARD_HEIGHT, 20);
  ctx.fillStyle = rgb(239, 239, 239);
  ctx.fill();

  const shieldW = 56;
  const shieldH = shieldW * 1.12;
  ctx.save();
  shieldPath(ctx, 16, 24, shieldW, shieldH);
  ctx.shadowColor = theme.glow;
  ctx.shadowBlur = 18;
  ctx.shadowOffsetY = 4;
  ctx.fillStyle = rgb(220, 220, 220);
  ctx.fill();
  ctx.restore();

  ctx.save();
  shieldPath(ctx, 16, 24, shieldW, shieldH);
  ctx.clip();
  drawMotifPattern(ctx, patternIdx, 16, 24, shieldW, shieldH);
  ctx.restore();

  ctx.save();
  ctx.beginPath();
  ctx.roundRect(0, 0, CARD_WIDTH, CARD_HEIGHT, 20);
  ctx.clip();
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";

  let y = 106.72;
  ctx.font = `400 16px ${CARD_FONT}`;
  ctx.fillStyle = rgb(131, 131, 131);
  ctx.fillText(card.house, 16, y);

  ctx.font = `700 33px ${CARD_FONT}`;
  ctx.fillStyle = rgb(12, 12, 14);
  y = wrapText(ctx, card.title, 16, y + 36, CARD_WIDTH - 32, 33 * 0.97, 5);

  ctx.font = `400 16px ${CARD_FONT}`;
  ctx.fillStyle = rgb(70, 70, 70);
  wrapText(ctx, card.body, 16, y + 14, CARD_WIDTH - 32, 16 * 1.24, 4);

  const pillsY = CARD_HEIGHT - 87;
  const durationLabel = card.duration ?? "0:18";
  const moreLabel = `+${card.extraCount ?? 12}`;
  ctx.font = `500 14px ${CARD_FONT}`;
  ctx.textBaseline = "middle";
  let cursor = 16;
  for (let i = 0; i < 3; i++) {
    const pillW = 40 + ctx.measureText(durationLabel).width + 8;
    ctx.beginPath();
    ctx.roundRect(cursor, pillsY, pillW, 40, 20);
    ctx.fillStyle = rgb(255, 255, 255, 0.78);
    ctx.fill();
    drawAvatarDot(ctx, cursor + 20, pillsY + 20, 16, card.id + i);
    ctx.fillStyle = rgb(131, 131, 131);
    ctx.fillText(durationLabel, cursor + 40, pillsY + 21);
    cursor += pillW + 4;
  }
  const moreW = 16 + ctx.measureText(moreLabel).width;
  ctx.beginPath();
  ctx.roundRect(cursor, pillsY, moreW, 40, 20);
  ctx.fillStyle = rgb(255, 255, 255, 0.78);
  ctx.fill();
  ctx.fillStyle = rgb(131, 131, 131);
  ctx.fillText(moreLabel, cursor + 8, pillsY + 21);
  ctx.textBaseline = "alphabetic";

  ctx.fillStyle = rgb(242, 242, 242);
  ctx.fillRect(0, CARD_HEIGHT - 38, CARD_WIDTH, 38);
  ctx.strokeStyle = rgb(0, 0, 0, 0.08);
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(0, CARD_HEIGHT - 38);
  ctx.lineTo(CARD_WIDTH, CARD_HEIGHT - 38);
  ctx.stroke();

  ctx.font = `400 12px ${CARD_FONT}`;
  ctx.fillStyle = rgb(131, 131, 131);
  ctx.textAlign = "center";
  wrapText(ctx, footerNote, CARD_WIDTH / 2, CARD_HEIGHT - 22, CARD_WIDTH - 36, 14, 2);
  ctx.restore();
}

export function buildCardTexturePair(
  cards: SpiralCardItem[],
  footerNote: string,
  scale: number,
  maxAnisotropy: number,
): { fronts: CanvasTexture[]; backs: CanvasTexture[] } {
  const fronts: CanvasTexture[] = [];
  const backs: CanvasTexture[] = [];
  for (let i = 0; i < cards.length; i++) {
    const frontCanvas = document.createElement("canvas");
    const backCanvas = document.createElement("canvas");
    paintCardFront(frontCanvas, cards[i], footerNote, scale);
    paintCardBack(backCanvas, cards[i].patternIndex ?? i, scale);

    const frontTex = new CanvasTexture(frontCanvas);
    frontTex.colorSpace = NoColorSpace;
    frontTex.anisotropy = Math.min(8, maxAnisotropy);
    frontTex.minFilter = LinearMipmapLinearFilter;

    const backTex = new CanvasTexture(backCanvas);
    backTex.colorSpace = NoColorSpace;
    backTex.anisotropy = Math.min(8, maxAnisotropy);

    fronts.push(frontTex);
    backs.push(backTex);
  }
  return { fronts, backs };
}

section/split-dropdown-navbar.code:
"use client";

import { useEffect, useState, type MouseEvent } from "react";
import { RollingCtaButton } from "@registry/ui/rolling-cta-button/component";
import {
  DesktopCategoryDropdown,
  MobileNavDrawer,
  type NavbarCategoryItem,
  type NavbarLinkItem,
} from "./navbar-menus";
import styles from "./styles.module.css";

export type { NavbarCategoryItem, NavbarLinkItem };

export interface SplitDropdownNavbarProps {
  brandName?: string;
  brandHref?: string;
  brandLogoSrc?: string;
  dropdownTitle?: string;
  dropdownAllLabel?: string;
  dropdownAllHref?: string;
  categories?: NavbarCategoryItem[];
  primaryLinks?: NavbarLinkItem[];
  drawerLinks?: NavbarLinkItem[];
  ctaLabel?: string;
  ctaHref?: string;
  ctaExternal?: boolean;
  onOpenSearch?: () => void;
  onDrawerToggle?: (open: boolean) => void;
  onNavigate?: (href: string, event: MouseEvent<HTMLAnchorElement>) => void;
  hideOnScroll?: boolean;
}

const DEFAULT_CATEGORIES: NavbarCategoryItem[] = [
  { id: "africa", label: "Africa", href: "#africa" },
  { id: "asia", label: "Asia", href: "#asia" },
  { id: "caribbean", label: "Central America & Caribbean", href: "#caribbean" },
  { id: "north-america", label: "North America", href: "#north-america" },
  { id: "south-america", label: "South America", href: "#south-america" },
  { id: "europe", label: "Europe & Mediterranean", href: "#europe" },
];

const DEFAULT_PRIMARY_LINKS: NavbarLinkItem[] = [
  { label: "Featured", href: "#featured" },
  { label: "Brochures", href: "#brochures" },
  { label: "Stories", href: "#stories" },
];

const DEFAULT_DRAWER_LINKS: NavbarLinkItem[] = [
  { label: "Partner Agencies", href: "#partners" },
  { label: "Traveler Hub", href: "#travelers", hasBorder: true },
  { label: "About Us", href: "#about" },
  { label: "Contact", href: "#contact" },
];

function BrandMarkSvg({ label }: { label: string }) {
  return (
    <svg viewBox="0 0 154 31" fill="none" className={styles.logo} aria-label={label}>
      <circle cx="15.5" cy="15.5" r="13.5" stroke="currentColor" strokeWidth="2" />
      <path d="M8 15.5H23M15.5 8V23" stroke="currentColor" strokeWidth="1.5" />
      <text x="38" y="21" fill="currentColor" fontFamily="serif" fontSize="18" fontWeight="600" letterSpacing="0.04em">
        {label.toUpperCase()}
      </text>
    </svg>
  );
}

function SearchSvg() {
  return (
    <svg width="23" height="23" viewBox="0 0 23 23" fill="none" aria-hidden="true">
      <circle cx="11.3" cy="11.3" r="7" transform="rotate(-45 11.3 11.3)" stroke="currentColor" strokeWidth="2" />
      <path d="M16.2 16.2L21.9 21.9" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
    </svg>
  );
}

function DownArrowSvg() {
  return (
    <svg className={styles.dropdownCaret} viewBox="0 0 13 11" fill="none" aria-hidden="true">
      <path d="M1 1.5H9V9.5M9 9.5L6 6.5M9 9.5L12 6.5" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

export function SplitDropdownNavbar({
  brandName = "Meridian",
  brandHref = "#top",
  brandLogoSrc,
  dropdownTitle = "Destinations",
  dropdownAllLabel = "View all destinations",
  dropdownAllHref = "#destinations",
  categories = DEFAULT_CATEGORIES,
  primaryLinks = DEFAULT_PRIMARY_LINKS,
  drawerLinks = DEFAULT_DRAWER_LINKS,
  ctaLabel = "Travel agent space",
  ctaHref = "#portal",
  ctaExternal = false,
  onOpenSearch,
  onDrawerToggle,
  onNavigate,
  hideOnScroll = true,
}: SplitDropdownNavbarProps) {
  const [isHidden, setIsHidden] = useState(false);
  const [isNavOpen, setIsNavOpen] = useState(false);
  const [isDesktopDropdownOpen, setIsDesktopDropdownOpen] = useState(false);

  useEffect(() => {
    let lastY = window.scrollY;
    const onScroll = () => {
      if (!hideOnScroll) return;
      const cur = window.scrollY;
      setIsHidden(cur > lastY && cur > 40);
      lastY = cur;
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        setIsDesktopDropdownOpen(false);
        setIsNavOpen(false);
      }
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    document.addEventListener("keydown", onKeyDown);
    return () => {
      window.removeEventListener("scroll", onScroll);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [hideOnScroll]);

  useEffect(() => {
    onDrawerToggle?.(isNavOpen);
  }, [isNavOpen, onDrawerToggle]);

  const closeAll = () => {
    setIsDesktopDropdownOpen(false);
    setIsNavOpen(false);
  };

  const headerCls = [
    styles.header,
    isHidden && !isNavOpen && !isDesktopDropdownOpen ? styles.isHidden : "",
    isNavOpen ? styles.navOpen : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <header className={headerCls}>
      <a
        href={brandHref}
        className={styles.logoLink}
        onClick={(e) => {
          closeAll();
          onNavigate?.(brandHref, e);
        }}
      >
        {brandLogoSrc ? (
          <img src={brandLogoSrc} className={styles.logo} alt={brandName} />
        ) : (
          <BrandMarkSvg label={brandName} />
        )}
      </a>

      <div className={styles.right}>
        <ul className={styles.mainLinks}>
          <li className={`${styles.mainLinkWrapper} ${styles.hasDropdown} ${isDesktopDropdownOpen ? styles.isOpened : ""}`.trim()}>
            <a
              href={dropdownAllHref}
              className={styles.mainLink}
              onClick={(e) => {
                e.preventDefault();
                setIsDesktopDropdownOpen((v) => !v);
                setIsNavOpen(false);
              }}
            >
              <span className={styles.labelRoll} data-label={dropdownTitle}>
                <span>{dropdownTitle}</span>
              </span>
              <DownArrowSvg />
            </a>
            <DesktopCategoryDropdown
              isOpen={isDesktopDropdownOpen}
              categories={categories}
              dropdownAllHref={dropdownAllHref}
              dropdownAllLabel={dropdownAllLabel}
              onClose={closeAll}
              onNavigate={onNavigate}
            />
          </li>

          {primaryLinks.map((item) => (
            <li key={item.href} className={styles.mainLinkWrapper}>
              <a
                href={item.href}
                className={styles.mainLink}
                onClick={(e) => {
                  closeAll();
                  onNavigate?.(item.href, e);
                }}
              >
                <span className={styles.labelRoll} data-label={item.label}>
                  <span>{item.label}</span>
                </span>
              </a>
            </li>
          ))}
        </ul>

        <button
          type="button"
          className={styles.searchToggle}
          aria-label="Search"
          onClick={() => {
            closeAll();
            onOpenSearch?.();
          }}
        >
          <SearchSvg />
        </button>

        <RollingCtaButton
          href={ctaHref}
          external={ctaExternal}
          label={ctaLabel}
          variant="primary"
          isFixed
          isSmall
          className={styles.desktopCta}
          onClick={(e) => onNavigate?.(ctaHref, e as MouseEvent<HTMLAnchorElement>)}
        />

        <button
          type="button"
          className={styles.menuToggle}
          aria-label="Menu"
          aria-expanded={isNavOpen}
          onClick={() => setIsNavOpen((v) => !v)}
        >
          <span />
          <span />
          <span />
        </button>
      </div>

      <MobileNavDrawer
        isOpen={isNavOpen}
        dropdownTitle={dropdownTitle}
        dropdownAllHref={dropdownAllHref}
        primaryLinks={primaryLinks}
        drawerLinks={drawerLinks}
        onClose={closeAll}
        onNavigate={onNavigate}
      />
    </header>
  );
}

