section/story-chances-list.code:
"use client";

import { useEffect, useRef, useState } from "react";
import { CREST_MASK_URL, CREST_PATTERNS, DEFAULT_STORY_IMAGES } from "./artwork";
import styles from "./styles.module.css";

export interface StoryChanceItem {
  title: string;
  description: string;
  imageUrl?: string;
  imageAlt?: string;
}

export interface StoryChancesListProps {
  id?: string;
  label?: string;
  chapter?: string;
  headlineTopPrefix?: string;
  headlineTopSuffix?: string;
  headlineBottom?: string;
  subtitle?: string;
  itemPrefix?: string;
  items?: StoryChanceItem[];
  crestPatterns?: string[];
  className?: string;
}

const DEFAULT_ITEMS: StoryChanceItem[] = [
  {
    title: "To linger at a new table.",
    description:
      "You stepped out for one brief errand. Hours later you are trading stories with people you had never met at noon.",
  },
  {
    title: "To walk an empty street.",
    description:
      "Nobody watching, nothing to broadcast. Just quiet air in a corner of the city you seldom see at this hour.",
  },
  {
    title: "To notice the hidden doorway.",
    description:
      "A lane you pass every Tuesday. A courtyard you never tried. It has been waiting around the corner all along.",
  },
  {
    title: "To see the hard part vanish.",
    description:
      "The task you postponed for a month took four minutes in practice. After that, the weight simply disappeared.",
  },
  {
    title: "To return with a real story.",
    description:
      "Not a saved post or a clipped frame. An afternoon that actually unfolded while you were standing right in it.",
  },
];

function prefersReducedMotion(): boolean {
  return (
    typeof window !== "undefined" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  );
}

function isCoarsePointer(): boolean {
  return typeof window !== "undefined" && window.matchMedia("(pointer: coarse)").matches;
}

export function StoryChancesList({
  id,
  label = "About Journey",
  chapter = "Chapter 03",
  headlineTopPrefix = "It starts as one",
  headlineTopSuffix = "step.",
  headlineBottom = "It rarely stays small.",
  subtitle = "No promises. Just what tends to unfold once you begin.",
  itemPrefix = "A chance",
  items = DEFAULT_ITEMS,
  crestPatterns = CREST_PATTERNS,
  className,
}: StoryChancesListProps) {
  const headRef = useRef<HTMLHeadingElement>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const [headInView, setHeadInView] = useState(false);
  const [activeCrest, setActiveCrest] = useState(0);

  // Trigger headline entry animation when in view
  useEffect(() => {
    const el = headRef.current;
    if (prefersReducedMotion() || !el || typeof IntersectionObserver === "undefined") {
      setHeadInView(true);
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) setHeadInView(true);
      },
      { threshold: 0.25 },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Rotate masked crest pattern every 1.4s while visible
  useEffect(() => {
    if (prefersReducedMotion() || !headInView || crestPatterns.length <= 1) return;
    const timer = window.setInterval(() => {
      setActiveCrest((prev) => (prev + 1) % crestPatterns.length);
    }, 1400);
    return () => window.clearInterval(timer);
  }, [headInView, crestPatterns.length]);

  // Reveal each row (--rp: 1) via IntersectionObserver
  useEffect(() => {
    const list = listRef.current;
    if (!list) return;
    const rows = Array.from(list.children) as HTMLElement[];

    if (prefersReducedMotion() || typeof IntersectionObserver === "undefined") {
      rows.forEach((row) => row.style.setProperty("--rp", "1"));
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            (entry.target as HTMLElement).style.setProperty("--rp", "1");
            observer.unobserve(entry.target);
          }
        }
      },
      { threshold: 0.12 },
    );

    rows.forEach((row) => observer.observe(row));
    return () => observer.disconnect();
  }, [items.length]);

  // Smooth pointer-proximity horizontal parallax on row photos
  useEffect(() => {
    const list = listRef.current;
    if (!list || isCoarsePointer() || prefersReducedMotion()) return;

    let mouseX = -1;
    let mouseY = -1;
    const onMove = (e: MouseEvent) => {
      mouseX = e.clientX;
      mouseY = e.clientY;
    };
    window.addEventListener("mousemove", onMove, { passive: true });

    const offsets: number[] = [];
    let rafId = 0;

    const frame = () => {
      const rect = list.getBoundingClientRect();
      const visible = rect.bottom > 0 && rect.top < window.innerHeight;
      for (let i = 0; i < list.children.length; i++) {
        const photo = list.children[i].children[1] as HTMLElement | undefined;
        if (!photo) continue;
        let target = 0;
        if (visible && mouseX >= 0) {
          const box = photo.getBoundingClientRect();
          const cx = box.left + box.width / 2;
          const cy = box.top + box.height / 2;
          const falloff = 1 / (1 + ((mouseY - cy) / 140) ** 2);
          target = Math.max(-60, Math.min(60, (mouseX - cx) * 0.16)) * falloff;
        }
        offsets[i] = (offsets[i] ?? 0) + (target - (offsets[i] ?? 0)) * 0.12;
        photo.style.transform = `translateX(${offsets[i].toFixed(1)}px)`;
      }
      rafId = requestAnimationFrame(frame);
    };

    rafId = requestAnimationFrame(frame);
    return () => {
      window.removeEventListener("mousemove", onMove);
      cancelAnimationFrame(rafId);
    };
  }, [items.length]);

  const sectionClass = [styles.section, className ?? ""].filter(Boolean).join(" ");

  return (
    <section id={id} className={sectionClass}>
      <div className={styles.colontitle} aria-hidden="true">
        <span>{label}</span>
        <span className={styles.colontitleRight}>{chapter}</span>
      </div>
      <div className={styles.inner}>
        <h2 ref={headRef} className={`${styles.head} ${headInView ? styles.headIn : ""}`}>
          <span className={styles.headLine}>
            {headlineTopPrefix}{" "}
            <span className={styles.questWrap}>
              <span
                className={styles.crest}
                aria-hidden="true"
                style={{ WebkitMaskImage: CREST_MASK_URL, maskImage: CREST_MASK_URL }}
              >
                {crestPatterns.map((src, i) => (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img
                    key={i}
                    src={src}
                    alt=""
                    width={160}
                    height={158}
                    decoding="async"
                    style={{
                      opacity: i === activeCrest ? 1 : 0,
                      transform: i === activeCrest ? "translateY(0)" : "translateY(45%)",
                    }}
                  />
                ))}
              </span>
              {"\u00A0"}
              {headlineTopSuffix}
            </span>
          </span>
          <span className={styles.headLine}>{headlineBottom}</span>
        </h2>
        <p className={styles.sub}>{subtitle}</p>
        <div className={styles.list} ref={listRef}>
          {items.map((item, i) => {
            const imgSrc =
              item.imageUrl ?? DEFAULT_STORY_IMAGES[i % DEFAULT_STORY_IMAGES.length];
            return (
              <div key={`${item.title}-${i}`} className={styles.row}>
                <div className={styles.itemLeft}>
                  <div>
                    <p className={styles.itemLabel}>{itemPrefix}</p>
                    <p className={styles.itemTitle}>{item.title}</p>
                  </div>
                  <p className={styles.itemNum}>{String(i + 1).padStart(2, "0")}</p>
                </div>
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img
                  className={styles.itemPhoto}
                  src={imgSrc}
                  alt={item.imageAlt ?? ""}
                  aria-hidden={item.imageAlt ? undefined : true}
                  width={600}
                  height={400}
                  loading="lazy"
                  decoding="async"
                />
                <p className={styles.itemDesc}>{item.description}</p>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

section/story-chances-list.stylesCss:
.section {
  position: relative;
  z-index: 5;
  color: var(--rk-bg);
  background: color-mix(in srgb, var(--rk-fg) 98%, var(--rk-bg));
  font-family: var(--rk-font-body);
  font-size: 16px;
  font-weight: 400;
  line-height: normal;
  border-radius: 24px;
  overflow-x: clip;
}

.section :focus-visible {
  outline: 2px solid var(--rk-bg);
  outline-offset: 4px;
}

.colontitle {
  position: absolute;
  top: 25px;
  left: 32px;
  right: 32px;
  z-index: 6;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  white-space: nowrap;
  pointer-events: none;
  color: var(--rk-bg);
  font-family: var(--rk-font-body);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.31;
}

.colontitleRight {
  text-align: right;
}

.inner {
  padding: 80px 40px 14vh;
}

.head {
  font-family: var(--rk-font-display);
  text-transform: uppercase;
  letter-spacing: -0.01em;
  margin: 0;
  font-size: clamp(40px, 6.2vw, 92px);
  font-weight: 300;
  line-height: 0.88;
  color: var(--rk-bg);
}

.headLine {
  display: block;
  opacity: 0;
  transform: translateY(0.42em);
}

.headIn .headLine {
  animation: 0.8s cubic-bezier(0.22, 1, 0.36, 1) forwards headRise;
}

.headIn .headLine:nth-child(2) {
  animation-delay: 0.12s;
}

@keyframes headRise {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.questWrap {
  white-space: nowrap;
}

.crest {
  vertical-align: -0.14em;
  width: 0.88em;
  height: 0.88em;
  display: inline-block;
  position: relative;
  -webkit-mask-size: 100% 100%;
  mask-size: 100% 100%;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
}

.crest img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: opacity 0.55s, transform 0.55s cubic-bezier(0.22, 1, 0.36, 1);
}

.sub {
  color: color-mix(in srgb, var(--rk-bg) 60%, transparent);
  max-width: 471px;
  margin: 26px 0 0;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.24;
}

.list {
  margin-top: 56px;
}

.row {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: stretch;
  column-gap: 5%;
  min-height: 169px;
  padding-top: 17px;
}

.row::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: color-mix(in srgb, var(--rk-bg) 10%, transparent);
  transform: scaleX(var(--rp, 0));
  transform-origin: 50%;
  transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1);
}

.itemLeft {
  width: 100%;
  max-width: 331px;
  display: flex;
  flex-direction: column;
  transform: translateX(calc((1 - var(--rp, 0)) * 17vw));
  opacity: var(--rp, 0);
  transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.65s ease;
}

.itemLabel {
  color: color-mix(in srgb, var(--rk-bg) 60%, transparent);
  margin: 0;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.24;
}

.itemTitle {
  color: var(--rk-bg);
  margin: 3px 0 0;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.12;
}

.itemNum {
  color: color-mix(in srgb, var(--rk-bg) 60%, transparent);
  margin: auto 0 17px;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.3125;
}

.itemPhoto {
  display: block;
  object-fit: cover;
  align-self: start;
  width: clamp(170px, 14vw, 201px);
  height: clamp(112px, 9.2vw, 133px);
  clip-path: inset(calc((1 - var(--rp, 0)) * 50%));
  transition: clip-path 0.65s cubic-bezier(0.22, 1, 0.36, 1);
}

.itemDesc {
  color: color-mix(in srgb, var(--rk-bg) 60%, transparent);
  width: 100%;
  max-width: 335px;
  justify-self: end;
  margin: 0;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.24;
  transform: translateX(calc((1 - var(--rp, 0)) * -17vw));
  opacity: var(--rp, 0);
  transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.65s ease;
}

@media (max-width: 768px) {
  .colontitle { top: max(25px, env(safe-area-inset-top)); left: 16px; right: 16px; }
  .inner { padding: 46px 16px 12vh; }
  .head { font-size: clamp(33px, 10.2vw, 40px); }
  .sub { display: none; }
  .list { margin-top: 34px; }
  .row {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 9px;
    min-height: 0;
    margin-bottom: 13px;
    padding-top: 14px;
  }
  .row::before { transform: none; }
  .itemLeft {
    opacity: 1;
    flex-direction: row;
    justify-content: space-between;
    align-items: flex-end;
    gap: 14px;
    width: 100%;
    max-width: none;
    transform: none;
  }
  .itemLeft > div { flex: auto; min-width: 0; }
  .itemNum { white-space: nowrap; margin: 0; }
  .itemPhoto {
    aspect-ratio: 153 / 101;
    clip-path: none;
    align-self: flex-start;
    width: min(153px, 42vw);
    height: auto;
  }
  .itemDesc { opacity: 1; place-self: stretch start; width: 100%; max-width: none; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .headLine { opacity: 1; transform: none; animation: none; }
  .row::before,
  .itemLeft,
  .itemPhoto,
  .itemDesc,
  .crest img {
    opacity: 1;
    transform: none;
    clip-path: none;
    transition: none;
  }
}

